#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

int counter = 2;

void handler(int sig) {
  counter--;
  printf("1");
  exit(0);
}

int main() {
  printf("2");
  pid_t pid = fork();
  if (pid == 0) {
    signal(SIGUSR1, handler);
    while (1);
  } else {
    sleep(1);
    kill(pid, SIGUSR1);
    wait(NULL);
    counter++;
    printf("3");
  }
  return 0;
}
